tool_input.content:
import fs from 'node:fs'

const gj = JSON.parse(fs.readFileSync('zhi2-web-admin/src/assets/images/dashboard/yixing.json', 'utf8'))
const feat = gj.features[0]
const name = feat.properties.name // 宜兴市
const code = String(feat.properties.adcode) // 320282
const geom = feat.geometry
// MultiPolygon: coordinates = [ [ ring, ... ], ... ]; Polygon: [ ring, ... ]
let polygons
if (geom.type === 'Polygon') polygons = [geom.coordinates]
else polygons = geom.coordinates

// collect all lng/lat for bbox
let minLng = Infinity, maxLng = -Infinity, minLat = Infinity, maxLat = -Infinity
function walk(rings, fn) {
  for (const ring of rings) for (const [lng, lat] of ring) fn(lng, lat)
}
for (const poly of polygons) walk(poly, (lng, lat) => {
  if (lng < minLng) minLng = lng
  if (lng > maxLng) maxLng = lng
  if (lat < minLat) minLat = lat
  if (lat > maxLat) maxLat = lat
})

const W = 900
const pad = 20
const availW = W - pad * 2
// Mercator y
const mercY = (lat) => Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI / 180) / 2))
const mercX = (lng) => lng * Math.PI / 180
const x0 = mercX(minLng), x1 = mercX(maxLng)
const yTop = mercY(maxLat), yBot = mercY(minLat)
const scale = availW / (x1 - x0)
const H = Math.round((yTop - yBot) * scale + pad * 2)

function project(lng, lat) {
  const px = pad + (mercX(lng) - x0) * scale
  const py = pad + (yTop - mercY(lat)) * scale
  return [Math.round(px * 100) / 100, Math.round(py * 100) / 100]
}

const polyStrs = polygons.map(poly => {
  // use outer ring only (holes ignored for county outline)
  const ring = poly[0]
  const pts = ring.map(([lng, lat]) => project(lng, lat).join(' ')).join(' ')
  return pts
})

const polygonsMarkup = polyStrs.map(pts =>
  `        <polygon id="${name}" name="${name}" code="${code}" points="${pts}" />`
).join('\n')

const svg = `<?xml version="1.0" encoding="UTF-8"?>
<svg width="${W}px" height="${H}px" viewBox="0 0 ${W} ${H}" version="1.1" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">
    <title>宜兴地图</title>
    <g id="页面-1" stroke="none" stroke-width="1" fill="none" fill-rule="evenodd">
        <g id="宜兴地图">
${polygonsMarkup}
        </g>
    </g>
</svg>
`

fs.writeFileSync('zhi2-web-admin/src/assets/images/dashboard/yixing.svg', svg, 'utf8')
console.log('WROTE yixing.svg', W, H, 'polygons:', polygons.length, 'ringPts:', polyStrs.map(s => s.split(' ').length / 2))

