# 宜兴公共收益 (zhi2-web-admin) 本地 nginx 部署 — root 指向本项目 dist（vite outDir = 仓库根/dist）
# 代理对齐 env/.env 的 VITE_APP_PROXY_ADDRESS = http://192.168.1.100，VITE_APP_BASE_API = 'api/v2.0'
# 前端请求 /api/v2.0/... 直连网关同路径
server {
    listen 8089;
    server_name localhost;
    root D:/repository/宜兴公共收益/dist;
    index index.html;
    charset utf-8;
    client_max_body_size 100m;

    proxy_http_version 1.1;
    proxy_set_header Connection "";
    proxy_set_header Host $proxy_host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_connect_timeout 60s;
    proxy_send_timeout 120s;
    proxy_read_timeout 120s;

    location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|map|xlsx|json)$ {
        expires 7d;
        add_header Cache-Control "public" always;
        access_log off;
        try_files $uri =404;
    }
    location = /index.html {
        expires -1;
        add_header Cache-Control "no-cache, no-store, must-revalidate";
        add_header Pragma "no-cache";
    }
    location = /version.json {
        add_header Cache-Control "no-cache, no-store, must-revalidate";
    }

    location ^~ /api/v2.0/ {
        proxy_pass http://192.168.1.100;
    }

    location / {
        try_files $uri $uri/ /index.html;
    }
}

