tool_input.content:
const fs = require('fs')
const s = fs.readFileSync('zhi2-web-admin/src/assets/images/dashboard/yixing.svg', 'utf8')
const m = s.match(/points="([^"]+)"/)
const nums = m[1].trim().split(/\s+/).map(Number)
const pts = []
for (let i = 0; i < nums.length; i += 2) pts.push([nums[i], nums[i + 1]])
let area = 0
for (let i = 0; i < pts.length; i++) {
  const j = (i + 1) % pts.length
  area += pts[i][0] * pts[j][1] - pts[j][0] * pts[i][1]
}
area = Math.abs(area / 2)
const xs = pts.map((p) => p[0])
const ys = pts.map((p) => p[1])
console.log('points:', pts.length, 'closed:', pts[0][0] === pts[pts.length - 1][0] && pts[0][1] === pts[pts.length - 1][1])
console.log('bbox x', Math.min(...xs).toFixed(1), Math.max(...xs).toFixed(1), 'y', Math.min(...ys).toFixed(1), Math.max(...ys).toFixed(1))
console.log('area', area.toFixed(0), 'viewBox area', 900 * 896)
